#!/usr/bin/env python3
"""MFRE (Fase 47 inc.D, D25): complete the French catalog
(launcher/lang/fr.json).

The 489 strings fr.json lacked (report: `python3 tools/mfre_lang_report.py
--dump fr`), in one alphabetical batch, validated the way `i18n::tests` does:
the {holes} of a value match its key's, and no value is empty. The catalog stays
sparse on purpose (philosophy of patch 0006); after this it is complete, like es.

    python3 tools/mfre_lang_fr.py --report   # counts only, nothing written
    python3 tools/mfre_lang_fr.py --apply    # write fr.json

# Terminology follows the existing catalog: Paramètres (Settings), Accueil (Home),
# Stockage (Storage), compiler/compilation (build), chargeur (loader), corbeille (Trash),
# journal (log), pack de ressources/de données/de shaders, Plus récente (Latest). Horizon
# stays Horizon where it names the upstream project, its registry or its services; the
# fork and its launcher say MineForge.
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

